CREATE COLUMN TABLE "TEST_AP"."ADP2" ("PrintId" NVARCHAR(4) NOT NULL , "RptType" NVARCHAR(20) NOT NULL , "EmailSbj" NVARCHAR(254), "EmailBody" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("PrintId", "RptType")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ADP2_OBJECT" ON "TEST_AP"."ADP2" ( "RptType" ASC )